// Generated by cline-hook install opencode.
import { spawn } from "node:child_process";
import { randomBytes } from "node:crypto";

const BINARY: string = "__CLINE_HOOK_BINARY__";
const BLOCK_EXIT_CODE = 2;
const BASE62 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";

interface HookOutcome {
  blocked: boolean;
  message: string;
}

interface InputUpdate {
  updated_input: Record<string, unknown>;
  message?: string | null;
}

interface TextPart {
  id: string;
  sessionID: string;
  messageID: string;
  type: "text";
  text: string;
  synthetic?: boolean;
}

interface Client {
  session: {
    get(options: { path: { id: string } }): Promise<{ data?: { parentID?: string } }>;
    promptAsync(options: { path: { id: string }; body: { parts: { type: "text"; text: string }[] } }): Promise<unknown>;
  };
  mcp: { status(): Promise<{ data?: Record<string, unknown> }> };
}

interface PluginInput {
  client: Client;
  directory: string;
}

function runHook(payload: Record<string, unknown>): Promise<HookOutcome> {
  return new Promise((resolve) => {
    const child = spawn(BINARY, [], { env: { ...process.env, CLINE_HOOKS_FRONTEND: "opencode" } });
    let stdout = "";
    let stderr = "";
    child.stdout.on("data", (chunk) => (stdout += chunk));
    child.stderr.on("data", (chunk) => (stderr += chunk));
    child.on("error", () => resolve({ blocked: false, message: "" }));
    child.on("close", (code) => {
      if (code === BLOCK_EXIT_CODE) resolve({ blocked: true, message: stderr.trim() });
      else resolve({ blocked: false, message: code === 0 ? stdout.trim() : "" });
    });
    child.stdin.end(JSON.stringify(payload));
  });
}

function parseInputUpdate(output: string): InputUpdate | undefined {
  if (!output.startsWith("{")) return undefined;
  try {
    const parsed = JSON.parse(output);
    if (parsed && typeof parsed.updated_input === "object" && parsed.updated_input !== null) return parsed;
  } catch {
    return undefined;
  }
  return undefined;
}

let partCounter = 0;

function partId(): string {
  partCounter = (partCounter + 1) % 4096;
  const stamp = BigInt(Date.now()) * 4096n + BigInt(partCounter);
  const time = stamp.toString(16).padStart(12, "0").slice(-12);
  return `prt_${time}${Array.from(randomBytes(14), (byte) => BASE62[byte % 62]).join("")}`;
}

function sanitize(name: string): string {
  return name.replace(/[^a-zA-Z0-9_-]/g, "_");
}

export const ClineHooks = async ({ client, directory }: PluginInput) => {
  const parents = new Map<string, Promise<string | undefined>>();
  const agents = new Map<string, string>();
  const started = new Set<string>();
  const stopActive = new Set<string>();
  const followUps = new Set<string>();
  const notes = new Map<string, string[]>();
  let mcpServers: Promise<string[]> | undefined;

  const parentOf = (id: string) => {
    let parent = parents.get(id);
    if (!parent) {
      parent = client.session.get({ path: { id } }).then(
        (result) => result.data?.parentID,
        () => undefined,
      );
      parents.set(id, parent);
    }
    return parent;
  };

  const toolName = async (tool: string) => {
    mcpServers ??= client.mcp.status().then(
      (result) => Object.keys(result.data ?? {}),
      () => [],
    );
    for (const server of await mcpServers) {
      const prefix = `${sanitize(server)}_`;
      if (tool.startsWith(prefix)) return `mcp__${server}__${tool.slice(prefix.length)}`;
    }
    return tool;
  };

  const hook = async (sessionID: string, payload: Record<string, unknown>) => {
    const child = Boolean(await parentOf(sessionID));
    return runHook({
      session_id: sessionID,
      cwd: directory,
      agent_type: child ? (agents.get(sessionID) ?? "") : "",
      agent_id: child ? sessionID : undefined,
      ...payload,
    });
  };

  return {
    "chat.message": async (
      input: { sessionID: string; agent?: string },
      output: { message: { id: string }; parts: { type: string; text?: string; synthetic?: boolean }[] },
    ) => {
      const { sessionID } = input;
      if (input.agent) agents.set(sessionID, input.agent);
      if (followUps.delete(sessionID)) return;
      stopActive.delete(sessionID);
      const messages: string[] = [];
      if (!started.has(sessionID)) {
        started.add(sessionID);
        const { message } = await hook(sessionID, { hook_event_name: "session.created", source: "startup" });
        if (message) messages.push(message);
      }
      const prompt = output.parts.flatMap((part) => (part.type === "text" && !part.synthetic ? [part.text] : []));
      const { message } = await hook(sessionID, { hook_event_name: "chat.message", prompt: prompt.join("\n") });
      if (message) messages.push(message);
      for (const text of messages) {
        const part: TextPart = {
          id: partId(),
          sessionID,
          messageID: output.message.id,
          type: "text",
          text,
          synthetic: true,
        };
        output.parts.push(part);
      }
    },

    "tool.execute.before": async (
      input: { tool: string; sessionID: string; callID: string },
      output: { args: Record<string, unknown> },
    ) => {
      const outcome = await hook(input.sessionID, {
        hook_event_name: "tool.execute.before",
        tool_name: await toolName(input.tool),
        tool_input: output.args,
      });
      if (outcome.blocked) throw new Error(outcome.message);
      const update = parseInputUpdate(outcome.message);
      if (update) Object.assign(output.args, update.updated_input);
      const message = update ? update.message : outcome.message;
      if (message) notes.set(input.callID, [message]);
    },

    "tool.execute.after": async (
      input: { tool: string; sessionID: string; callID: string; args: Record<string, unknown> },
      output: { output: string },
    ) => {
      const pending = notes.get(input.callID) ?? [];
      notes.delete(input.callID);
      const { message } = await hook(input.sessionID, {
        hook_event_name: "tool.execute.after",
        tool_name: await toolName(input.tool),
        tool_input: input.args,
        tool_response: { success: true, result: output.output },
      });
      if (message) pending.push(message);
      if (pending.length) output.output = [output.output, ...pending].join("\n\n");
    },

    "experimental.session.compacting": async (input: { sessionID: string }, output: { context: string[] }) => {
      const { message } = await hook(input.sessionID, { hook_event_name: "experimental.session.compacting" });
      if (message) output.context.push(message);
    },

    event: async ({ event }: { event: { type: string; properties?: { sessionID?: string } } }) => {
      if (event.type !== "session.idle") return;
      const sessionID = event.properties?.sessionID;
      if (!sessionID || (await parentOf(sessionID))) return;
      const outcome = await hook(sessionID, {
        hook_event_name: "session.idle",
        stop_hook_active: stopActive.has(sessionID),
      });
      if (!outcome.blocked || !outcome.message) return;
      stopActive.add(sessionID);
      followUps.add(sessionID);
      await client.session.promptAsync({
        path: { id: sessionID },
        body: { parts: [{ type: "text", text: outcome.message }] },
      });
    },
  };
};
